import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"24、【复】 震下坤上","description":"周易阐真 - 24、【复】 震下坤上","frontmatter":{"title":"24、【复】 震下坤上","description":"周易阐真 - 24、【复】 震下坤上"},"headers":[],"relativePath":"zh/classics/chanzhen/025.md","filePath":"zh/classics/chanzhen/025.md"}'),s={name:"zh/classics/chanzhen/025.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：复，亨。刚反，动而以顺行。是以出入无疾，朋来无咎。反复其道，七日来复，天行也。利有攸往，刚长也。复，其见天地之心乎。</p></blockquote><h1 id="_24、【复】-震下坤上" tabindex="-1">24、【复】 震下坤上 <a class="header-anchor" href="#_24、【复】-震下坤上" aria-label="Permalink to “24、【复】 震下坤上”">​</a></h1><p>初九：不远复，无祗悔，元吉。</p><p>六二：休复，吉。</p><p>六三：频复，厉无咎。</p><p>六四：中行独复。</p><p>六五：敦复，无悔。</p><p>上六：迷复，凶，有灾眚。用行师，终有大败。以其国君凶，至于十年不克征。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：雷在地中，复。先王以至日闭关，商旅不行，后不省方。</p><p>复者，返还也。上坤地，下震雷，是雷在地中也。雷为至阳之物，阳动于地，生机回转，则万物生。</p><p>先王有见于此，知天之阳气回转，则万物苏生；人之阳气发现，则生机返还。以是于冬至之日闭关，商旅不得行而贸易，元后不得出而省方。凡此者，无非使人效法天地之复，养此一点生机，不得稍有伤损耳。生机者何?机即人本来秉彝天良之心，为生物之祖、阴阳之宗，一落后天，为气质所蔽，不能常现，间或一现，此即阴中返阳之时也。惟此一时，难得易失，人多不知，当面错过，所以阴渐长，阳渐消，阳尽阴纯，有死而已。至日闭关者，欲人人在阳之时养阳也；商旅不行者，使其不得务于外假，有伤内真也；后不省方者，使其不得明于责人，暗于修己也。一闭关而谨慎严密，内念不生，外物不入，阳气焉得而渗漏之?先王为天地立心，为生民立命者有如此。修道君子，炼己持心，虚室生白，生机回转，急须收入造化炉中，防危虑险，谨封牢藏，由微而著，必自一阳而渐于六阳纯全，亦即先王至日闭关之意。盖以此一阳来复之时，为生死之关口，得之则入于生路，失之则归于死路。闭关者，闭其死户也。死户闭而生门开，天借人力，人借天力，天人合发，则一时辰内管丹成，不待三年九载之功。其如人多不求真师口诀，每每当面错过，可不悲哉!</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>反复，复音覆。祗，音支。</p><p>复者，还返之义。卦德上坤顺，下震动，动作顺心，天运转，人事通。又卦体一阳动于群阴之下，阳气始回，二者均有复道，故谓复。此先天阴中复阳之卦，承上贲卦而来。贲者，明而止所以养明运火，采取先天真阳耳。采取真阳，乃阴中返阳，重整家事，别立鼎炉之道，能以夺造化，了生死，复而未有不亨者也。</p><p>复道虽亨，但人认假弃真，多不知其复耳。若知其复，则回头是岸，道心发现，人心自退，可以出入乎阴阳之中，而不为阴阳所疾伤矣。然虽无疾伤，须要复之知时，时未至而不可强求，时已至而不可错过，方能得真。</p><p>夫人当初生之时，至善无恶，及交后天，阴伤其阳，本来天真有失矣。虽是失去，未尝全无，犹有一息生机在内，间或发现，为私欲所瞒，为世事所混，当面不识耳。复之必乘此生机发现之时，下手急采，方能为我所有。若生机未现，空寂守静，将何而复乎?是以朋来而复，方能无咎。朋者，二月相合，其一为阳，其一为阴，阴极阳生，阴中有阳，是谓朋来。阴不极，阳不生，而朋不来。若朋不来，阴阳不交，生气自何而有?故必朋来而生机方发，生机发而不先不后，收入造化炉中，片刻之间，灾变为福，刑化为德，先因真阳失而有咎者，今则真阳还而可以无咎矣。</p><p>但复之虽能无咎，其道有功力，有次序，渐以复之，不能遽复，即复之也不能坚固，必先炼己持心，待时而动，是以反复其道，七日来复也。反复者，颠倒道运之义。七日者，阳火之数。人之性情和气，阳火也，为真；人之客气躁性，阴火也，为假。真者全生，假者伤生。反复其道者，先返此假火，复归于真火，七日而阳火生，阴火灭，虚极静笃，黑中有白，先天之气，自虚无中现象，渐采渐炼，还丹可结。但是道也，非知之艰，行之维艰，知之尤贵于行之。若知而不行，犹如无知。有攸往而下手速修，必自一阳而渐复，至于六阳纯全，其复之亨利，为何如耶？</p><p>初九，在复之初，真阳未失，稍有客气潜入而即退之，至容且易，是不远之复。不远复，而人心不生，道心常存，自无祗悔，能谨于始，自吉于终。此元阳不失之复也。</p><p>六二，知识有限，本不能明善复初者，然柔顺得正，见贤思齐，与有道之君子同处，借彼之明智，以破己之昏暗，不知复者亦知复，不能复者亦能复，是谓休善之复。此柔而借刚之复也。</p><p>六三，复善不固，旋复而旋失，是谓频复。然性柔志刚，一心于复，危厉自处。人一能之，己百之，人十能之，已千之，虽愚必明，虽柔必强，始而有咎者，终而可以无咎。此困而学、勉强而行之复也。</p><p>六四，柔而得正，居于群小之中，而不为群小所惑，借世法而修道法，独能明善复初者。此学而知、利而行之复也。</p><p>六五，柔顺得中，循规蹈矩，素位而行，不愿乎外，是谓敦厚。其复者，复于敦厚，不思而得，不勉而中，出于性成，既无所失，亦无可复，不致悔而自无悔。此生而知、安而行之复也。</p><p>上六，在复之终，顺其后天之阴，不知先天之阳，人心用事，道心全味，是迷于复，而终不知回头者，招凶致灾，势所必有。如此之人，途而不悟，外而争胜好强，内而心神大伤，如用行师，终有大败，祸及国君。虽十年之久，必有克征，终亦必亡而已。此始终不知有复也。</p><p>复有天时之复，有人事之复。天时之复，真阳发现，出于自然；人事之复，真阳坚固，出于功力。天时人事，两而合一，方能有济。六爻除上爻迷复，其余五爻，皆有复道。或安而行，或利而行，或勉强而行，总以复于元初本来面目为极功。</p>',25)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
